func BenchmarkUnbufferedWrite(b *testing.B) {
 performWrite(b, tmpFileOrFatal())
}
func BenchmarkBufferedWrite(b *testing.B) {
 bufferredFile := bufio.NewWriter(tmpFileOrFatal())
 performWrite(b, bufio.NewWriter(bufferredFile))
}
func tmpFileOrFatal() *os.File {
 file, err := ioutil.TempFile("", "tmp")
 if err != nil {
 log.Fatal("error: %v", err)
 }
 return file
}
func performWrite(b *testing.B, writer io.Writer) {
 done := make(chan interface{})
 defer close(done)
 b.ResetTimer()
 for bt := range take(done, repeat(done, byte(0)), b.N) {
 writer.Write([]byte{bt.(byte)})
 }
}
go test -bench=. src/concurrency-patterns-in-go/queuing/buffering_test.go
And here are the results of running this benchmark:
BenchmarkUnbufferedWrite-8 500000 3969 ns/op
BenchmarkBufferedWrite-8 1000000 1356 ns/op
PASS
ok command-line-arguments 3.398s
As anticipated, the buffered write is faster than the unbuffered write. This is because
in bufio.Writer, the writes are queued internally into a buffer until a sufficient
chunk has been accumulated, and then the chunk is written out. This process is often
called chunking, for obvious reasons.
Chunking is faster because bytes.Buffer must grow its allocated memory to accom‐
modate the bytes it must store. For various reasons, growing memory is expensive;
therefore, the less times we have to grow, the more efficient our system as a whole will
perform. Thus, queuing has increased the performance of our system as a whole.
